mkdir -p /tmp/rounding-probe && cd /tmp/rounding-probe && cat > probe.mjs <<'EOF'
const cur = (x) => Math.round(x * 100) / 100;
const viaEps = (x) => Math.round((x + Number.EPSILON) * 100) / 100;
const viaExp = (x) => Number(Math.round(Number(x + "e2")) + "e-2");
for (const x of [1.005, 1.234, 2.675, 1.015, 0.285, 1.45]) {
  console.log(x, "exact:", x.toPrecision(25).slice(0,22), "| current:", cur(x), "| epsilon:", viaEps(x), "| exp:", viaExp(x));
}
EOF
node -I probe.mjs

git checkout -b fix/round-half-up-cents && cat > src/money.js <<'EOF'
// Rounds an amount to cents, half up, on the decimal value as written (1.005 -> 1.01).
// Shifting the decimal point in the string avoids binary float error in x * 100.
export const roundCents = (x) => Math.round(Number(`${x}e2`)) / 100;
EOF
